def _f1_from_arrays(tp, gold, pred):
    p = np.where(pred > 0, tp / pred, 0.0)
    r = np.where(gold > 0, tp / gold, 0.0)
    denom = p + r
    return np.where(denom > 0, 2 * p * r / denom, 0.0)

def bootstrap_f1(sample_stats, n_bootstrap=10000, seed=42):
    rng = np.random.RandomState(seed)
    n = len(sample_stats)
    tps = np.array([s["tp"] for s in sample_stats])
    golds = np.array([s["gold"] for s in sample_stats])
    preds = np.array([s["pred"] for s in sample_stats])

    indices = rng.randint(0, n, size=(n_bootstrap, n))
    tp_sums = tps[indices].sum(axis=1).astype(float)
    gold_sums = golds[indices].sum(axis=1).astype(float)
    pred_sums = preds[indices].sum(axis=1).astype(float)

    f1_samples = _f1_from_arrays(tp_sums, gold_sums, pred_sums)

    point_p = tps.sum() / preds.sum() if preds.sum() > 0 else 0.0
    point_r = tps.sum() / golds.sum() if golds.sum() > 0 else 0.0
    point_f1 = 2 * point_p * point_r / (point_p + point_r) if (point_p + point_r) > 0 else 0.0

    return {
        "point_estimate": float(point_f1),
        "bootstrap_mean": float(np.mean(f1_samples)),
        "ci_lower": float(np.percentile(f1_samples, 2.5)),
        "ci_upper": float(np.percentile(f1_samples, 97.5)),
        "std": float(np.std(f1_samples)),
    }

